def on_same_diag(p1, p2):
    (r1,c1), (r2,c2) = p1, p2
    swne = r1-c1 == r2-c2  # SW-NE diagonal
    nwse = r1+c1 == r2+c2  # NW-SE diagonal
    return swne, nwse

